import re
import os

work_dir = '/tmp/hwpx_work'

print("=== Searching for all {{ placeholders ===")
placeholders_found = []

for root, dirs, files in os.walk(work_dir):
    for filename in files:
        filepath = os.path.join(root, filename)
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                if '{{' in content:
                    # Find all lines with {{
                    for i, line in enumerate(content.split('\n'), 1):
                        matches = re.findall(r'\{\{[^}]+\}\}', line)
                        for match in matches:
                            placeholders_found.append((filename, i, match))
                            print(f"  {filename}:{i} -> {match}")
        except Exception as e:
            print(f"  Could not read {filename}: {e}")

print(f"\n=== Total placeholders found: {len(placeholders_found)} ===")
for p in placeholders_found:
    print(f"  {p[2]}")

