# Step 4: Verify no placeholders remain
print("=== Step 4: Verifying no placeholders remain ===")
remaining_placeholders = []

for root_dir, dirs, files in os.walk(work_dir):
    for filename in files:
        filepath = os.path.join(root_dir, filename)
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                matches = re.findall(r'\{\{[^}]+\}\}', content)
                if matches:
                    remaining_placeholders.extend([(filename, m) for m in matches])
        except:
            pass

if remaining_placeholders:
    print("ERROR: Found remaining placeholders:")
    for filename, placeholder in remaining_placeholders:
        print(f"  {filename}: {placeholder}")
else:
    print("SUCCESS: No placeholders remain in any file")

# Also verify layout-cache elements were removed from modified paragraphs
print("\n=== Verifying layout-cache removal ===")
xml_path = os.path.join(work_dir, 'Contents', 'section0.xml')
